// Drift detection algorithm
const metrics = $input.all();
const DRIFT_THRESHOLD = parseFloat($env.MODEL_DRIFT_THRESHOLD || '3.0');
const driftAlerts = [];
const metricsReport = [];

for (const item of metrics) {
  const m = item.json;
  const driftPct = parseFloat(m.drift_pct || 0);
  const errorRate = m.total > 0 ? (m.errors / m.total * 100) : 0;

  const isDrifting = Math.abs(driftPct) > DRIFT_THRESHOLD;
  const isHighError = m.high_error_rate || errorRate > 10;

  metricsReport.push({
    model: m.task_type,
    total_predictions_24h: m.total,
    success_rate_pct: Math.round((m.successful / Math.max(m.total, 1)) * 100),
    avg_confidence: m.avg_confidence,
    confidence_drift_pct: driftPct,
    avg_response_ms: m.avg_time_ms,
    drift_detected: isDrifting,
    high_error_rate: isHighError,
    status: isDrifting || isHighError ? 'WARNING' : 'OK'
  });

  if (isDrifting || isHighError) {
    driftAlerts.push({
      model: m.task_type,
      issue: isDrifting ? `Confidence drift ${driftPct.toFixed(1)}% (threshold: ${DRIFT_THRESHOLD}%)` : `Error rate tinggi: ${errorRate.toFixed(1)}%`,
      severity: Math.abs(driftPct) > DRIFT_THRESHOLD * 2 || errorRate > 20 ? 'CRITICAL' : 'WARNING'
    });
  }
}

const overallHealth = driftAlerts.length === 0 ? 'HEALTHY' : 
                     driftAlerts.some(a => a.severity === 'CRITICAL') ? 'CRITICAL' : 'WARNING';

return [{
  json: {
    overall_health: overallHealth,
    drift_alerts: driftAlerts,
    metrics_report: metricsReport,
    models_checked: metricsReport.length,
    alerts_count: driftAlerts.length,
    check_timestamp: new Date().toISOString(),
    drift_threshold_pct: DRIFT_THRESHOLD
  }
}];

